MIME_LIVRABLES: Mapping[str, str] = MappingProxyType(
    {
        "rapport_xlsx": "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "rapport_pptx": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    }
)
"""Type MIME de chaque livrable téléchargeable."""

LIBELLES_LIVRABLES: Mapping[str, str] = MappingProxyType(
    {"rapport_xlsx": "Rapport quotidien (Excel)", "rapport_pptx": "Comité de pilotage (PowerPoint)"}
)
"""Libellé de chaque livrable, dans l'ordre d'affichage."""

AUCUN_PASSAGE = "Aucun Passage publié pour l'instant."
AUCUNE_METEO = "Ce Passage ne contient aucune Météo."
NON_GENERE = "Non généré pour ce Passage"


class LectureVueCarte(LectureCarte, Protocol):
    """Lectures de la carte et lecture d'un livrable (alignées sur `Consultation`)."""

    def livrable(self, nom: Literal["rapport_xlsx", "rapport_pptx"]) -> bytes | None:
        """Contenu du livrable `nom` du Passage lu, ou `None` s'il est absent (AD-11)."""
        ...


def taille_lisible(octets: int) -> str:
    """`850 o`, `12 Ko`, `1,2 Mo` (unités de 1 024, virgule décimale)."""
    if octets < 1024:
        return f"{octets} o"
    if octets < 1024 * 1024:
        return f"{round(octets / 1024)} Ko"
    return f"{octets / (1024 * 1024):.1f}".replace(".", ",") + " Mo"


def vue_meteo(couleur: Couleur) -> VueMeteo:
    """Couleur en donnée : code, libellé, pastille et texte `🔴 Rouge`."""
    return VueMeteo(
        couleur=couleur.value,
        libelle=LIBELLES_COULEURS[couleur],
        pastille=PASTILLES[couleur],
        texte=libelle_meteo(couleur),
    )


def entites_triees(meteos: Sequence[MeteoEntite]) -> list[MeteoEntite]:
    """Du plus grave au moins grave, puis par Entité."""
    par_entite = sorted(meteos, key=lambda meteo: meteo.entite)
    return sorted(par_entite, key=lambda meteo: meteo.couleur, reverse=True)


def vues_livrables(consultation: LectureVueCarte) -> list[VueLivrable]:
    """Un livrable par entrée de `MIME_LIVRABLES` ; absent : sans lien (`NON_GENERE`)."""
    date_arrete = consultation.manifeste().date_arrete
    vues: list[VueLivrable] = []
    for nom in MIME_LIVRABLES:
        livrable = cast(Literal["rapport_xlsx", "rapport_pptx"], nom)
        contenu = consultation.livrable(livrable)
        vues.append(
            VueLivrable(
                nom=livrable,
                libelle=LIBELLES_LIVRABLES[nom],
                nom_fichier=PurePosixPath(chemin_fichier_passage(nom, date_arrete)).name,
                disponible=contenu is not None,
                url=None if contenu is None else f"/livrables/{nom}",
                taille=None if contenu is None else taille_lisible(len(contenu)),
                message_absent=NON_GENERE if contenu is None else None,
            )
        )
    return vues


def _vue_ligne(
    meteo: MeteoEntite, evolution: EvolutionMeteo | None, url_ticket: Callable[[str], str | None]
) -> VueLigneCarte:
    cles = meteo.regles[0].tickets_en_cause if meteo.regles else ()
    return VueLigneCarte(
        entite=meteo.entite,
        url=f"/entites/{quote(meteo.entite, safe='')}",
        meteo=vue_meteo(meteo.couleur),
        tendance=tendance(evolution),
        regle_principale=regle_principale(meteo),
        tickets=[vue_ticket(cle, url_ticket(cle)) for cle in cles[:TICKETS_MAX]],
        tickets_restants=max(0, len(cles) - TICKETS_MAX),
    )


def vue_carte_vide(message: str | None, erreur: str | None = None) -> VueCarte:
    """Carte sans Passage lisible : message (avec « Lancer la Chaîne ») ou erreur de lecture."""
    return VueCarte(
        date_arrete=None,
        message=message,
        lancer_chaine=erreur is None,
        erreur=erreur,
        tuiles=[],
        filtre=[],
        messages_vides={},
        lignes=[],
        legende=LEGENDE,
        livrables=[],
    )


def vue_carte(consultation: LectureVueCarte) -> VueCarte:
    """Vue de la carte du Passage lu : tuiles, filtre, lignes triées et livrables."""
    meteos = entites_triees(consultation.meteo())
    date_arrete = date_carte(consultation)
    if not meteos:
        vide = vue_carte_vide(AUCUNE_METEO)
        return vide.model_copy(
            update={"date_arrete": date_arrete, "livrables": vues_livrables(consultation)}
        )
    evolutions = {evolution.entite: evolution for evolution in consultation.evolution_meteo()}
    couleurs = sorted(Couleur, reverse=True)
    return VueCarte(
        date_arrete=date_arrete,
        message=None,
        lancer_chaine=False,
        erreur=None,
        tuiles=[
            VueTuile(
                meteo=vue_meteo(couleur),
                nombre=sum(1 for meteo in meteos if meteo.couleur is couleur),
            )
            for couleur in couleurs
        ],
        filtre=[vue_meteo(couleur) for couleur in couleurs],
        messages_vides={
            couleur.value: f"Aucune Entité en {LIBELLES_COULEURS[couleur]} à cette Date d'arrêté."
            for couleur in couleurs
        },
        lignes=[
            _vue_ligne(meteo, evolutions.get(meteo.entite), consultation.url_ticket)
            for meteo in meteos
        ],
        legende=LEGENDE,
        livrables=vues_livrables(consultation),
    )
